{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Anecdotally, anecortave desacetate, a polyhydroxylated steroid closely related to the query scaffold, showed low oral bioavailability in a human 14C-excretion and metabolism study; the high transfer score supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Mometasone, a corticosteroid with multiple polar groups, has reported oral bioavailability below 1% in humans; this direct low-F measurement transfers strongly to the query's steroid-like polar structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Fluticasone has negligible (<1%) absolute oral bioavailability via gastrointestinal absorption in humans, indicating that a highly hydroxylated steroid-like molecule can have very low F; high transfer supports the low prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Oridonin, a polyhydroxylated diterpenoid with poor water solubility and unfavorable pharmacokinetics, has low oral bioavailability in humans; the shared high polarity and many hydroxyls support low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Danoprevir, a large polar molecule, had an absolute oral bioavailability of only 1.15% without ritonavir in healthy subjects; the high transfer score reinforces that high polarity and molecular size can produce F far below 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large, highly hydroxylated steroid-like molecule with high TPSA and six hydrogen-bond donors. Multiple high-transfer experimental analogues—especially corticosteroids and related polyhydroxylated natural products—show very low oral bioavailability in humans, often below 10% or even below 1%. The physicochemical prior and the consistent experimental evidence both point to F < 20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the query molecule.",
    "The exact roles of intestinal permeability, P-glycoprotein efflux, and hepatic first-pass metabolism in the query are not directly measured.",
    "One analogue (ursolic acid) showed some oral bioavailability, but no quantitative F value was reported, so it does not override the consistent low-F evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

